import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch79Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm8_en_190","xy7_en_082");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static EnergyProfile energy(){return NonPokemonBatch2Test.DATA.energyProfile(IDS.get(1)).orElseThrow();}
    static TrainerProfile tag(){return NonPokemonBatch2Test.DATA.trainer(IDS.getFirst()).orElseThrow();}
    static GeneratedRuleBatch28Test.Config config(boolean dangerous,AttackDefinition attack,Set<EnergyType> types){var c=new GeneratedRuleBatch28Test.Config();c.attack=attack;c.defenderAttack=attack;c.ownTypes=types;c.defenderTypes=types;if(dangerous)c.specialEnergy=energy();else c.trainer=tag();return c;}
    static ServerMatch fixture(GeneratedRuleBatch28Test.Config c,UUID p){var m=GeneratedRuleBatch28Test.fixture(c);if(p.equals(B))m.endTurn(A);return m;}
    static ServerMatch aiGame(String id){if(id.equals(IDS.getFirst()))return fixture(config(false,GeneratedRuleBatch8Test.hit(300,false),Set.of(EnergyType.PSYCHIC)),A);return DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),DynamicPassiveModifierTest.plainStadium(),energy(),GeneratedRuleBatch8Test.hit(100,false),List.of(),0,null,Map.of("basic",EnergyType.DARKNESS,"evolved",EnergyType.DARKNESS));}
    static CardInstance equip(ServerMatch m,UUID p,UUID host,boolean dangerous){var c=hand(m,p,dangerous?"energy":"trainer");if(dangerous)m.attachEnergyByEffect(p,p,EffectSourceZone.HAND,c.instanceId(),p,host);else m.playTrainer(p,c.instanceId(),host);return c;}
    static void triggerOrder(ServerMatch m){while(m.triggerOrderPrompt()!=null){var q=m.triggerOrderPrompt();m.chooseTriggeredEffect(q.choosingPlayer(),q.id(),q.entries().getFirst().id());}}
    public static void main(String[] args){dangerous();dangerousSequence();spell();spellCascade();metalGoggles();System.out.println("NonPokemonBatch79Test passed: exact legacy EX attackers, live Darkness hosts, Active-only actual damage, lethal and stacking retaliation, attacker switch and Energy discard timing; Psychic KO-only Spell Tag, exact split authority/stale protection, cascading KOs and Tool counters bypass Metal Goggles");}
    static void dangerous(){for(UUID p:List.of(A,B))for(PokemonFamily family:List.of(PokemonFamily.EX_LEGACY,PokemonFamily.EX,PokemonFamily.GX,PokemonFamily.V))for(boolean onBench:List.of(false,true))for(boolean lethal:List.of(false,true))for(int count:List.of(1,2)){
        var c=config(true,GeneratedRuleBatch8Test.hit(100,onBench),Set.of(EnergyType.DARKNESS));if(p.equals(A))c.defenderFamilies=Set.of(family);else c.ownFamilies=Set.of(family);var m=fixture(c,p);UUID host=onBench?bench(m,p):active(m,p);for(int i=0;i<count;i++)equip(m,p,host,true);if(lethal)NonPokemonBatch75Test.hurt(m,p,host,950);m.endTurn(p);m.attack(other(p),"hit");NonPokemonBatch67Test.settle(m);check(m.activePokemonView(other(p)).damage()==(!onBench&&family==PokemonFamily.EX_LEGACY?20*count:0),"Dangerous Energy confused EX/EX_LEGACY, position, lethal damage or stacking");
    }}
    static void dangerousSequence(){for(String mode:List.of("switch","discard","counters","zero","evolve")){
        String effect=switch(mode){case "switch"->"{\"type\":\"switch\",\"target\":\"SELECT_OWN_POKEMON\"}";case "discard"->"{\"type\":\"discard_energy\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":1,\"minimum\":1}";case "counters"->"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}";default->"";};var c=config(true,DeckDiscardTriggeredAbilityTest.attack(mode.equals("zero")||mode.equals("counters")?0:100,effect),Set.of(EnergyType.DARKNESS));c.defenderFamilies=Set.of(PokemonFamily.EX_LEGACY);var m=fixture(c,A);var en=equip(m,A,active(m,A),true);if(mode.equals("evolve")){m.evolveByEffect(A,active(m,A),hand(m,A,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);check(m.privateView(A).discard().contains(en),"Dangerous Energy remained on non-Darkness evolution");}UUID attacker=active(m,B);m.endTurn(A);m.attack(B,"hit");NonPokemonBatch67Test.settle(m);var view=EventTargetBindingTest.field(m).pokemonView(B,attacker);check(view.damage()==(mode.equals("switch")?20:0),"Dangerous Energy retaliation timing/source wrong: "+mode);if(mode.equals("switch"))check(!active(m,B).equals(attacker)&&m.activePokemonView(B).damage()==0,"Retaliation hit new Active instead of actual attacker");
    }}
    static void spell(){for(UUID p:List.of(A,B))for(Set<EnergyType> types:List.of(Set.of(EnergyType.PSYCHIC),Set.of(EnergyType.WATER),Set.of(EnergyType.PSYCHIC,EnergyType.WATER)))for(boolean onBench:List.of(false,true))for(boolean disabled:List.of(false,true))for(boolean counters:List.of(false,true)){
        var hit=counters?DeckDiscardTriggeredAbilityTest.attack(0,"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}"):GeneratedRuleBatch8Test.hit(100,onBench);var m=fixture(config(false,hit,types),p);UUID host=counters?active(m,p):onBench?bench(m,p):active(m,p),opp=other(p);equip(m,p,host,false);if(disabled)m.disableToolEffectsByEffect(p,p,host);NonPokemonBatch75Test.hurt(m,p,host,counters?980:950);m.endTurn(p);m.attack(opp,"hit");triggerOrder(m);boolean enabled=types.contains(EnergyType.PSYCHIC)&&!disabled&&!counters;check(m.hasPendingDamageAllocation()==enabled,"Spell Tag wrong type, damage cause or Tool suppression");if(enabled){var q=m.damageAllocationPrompt(p);check(q.budget()==4&&q.candidates().stream().allMatch(t->t.owner().equals(opp)),"Wrong Spell Tag allocation budget/scope");var invalid=List.of(new ServerMatch.DamageCounterPlacement(opp,active(m,opp),3));GeneratedRuleBatch8Test.reject(()->m.submitDamageAllocation(p,q.resolutionId(),q.step(),invalid));GeneratedRuleBatch8Test.reject(()->m.submitDamageAllocation(opp,q.resolutionId(),q.step(),List.of(new ServerMatch.DamageCounterPlacement(opp,active(m,opp),4))));GeneratedRuleBatch8Test.reject(()->m.submitDamageAllocation(p,q.resolutionId(),q.step(),List.of(new ServerMatch.DamageCounterPlacement(p,host,4))));check(m.activePokemonView(opp).damage()==0&&m.benchPokemonView(opp).getFirst().damage()==0,"Invalid allocation partially placed counters");m.submitDamageAllocation(p,q.resolutionId(),q.step(),List.of(new ServerMatch.DamageCounterPlacement(opp,active(m,opp),2),new ServerMatch.DamageCounterPlacement(opp,bench(m,opp),2)));GeneratedRuleBatch8Test.reject(()->m.submitDamageAllocation(p,q.resolutionId(),q.step(),invalid));}NonPokemonBatch67Test.settle(m);check(m.activePokemonView(opp).damage()==(enabled?20:0)&&m.benchPokemonView(opp).getFirst().damage()==(enabled?20:0)&&m.privateView(opp).prizes().size()==5,"Spell Tag wrong split or lost original KO Prize");
    }}
    static void spellCascade(){var m=fixture(config(false,GeneratedRuleBatch8Test.hit(100,false),Set.of(EnergyType.PSYCHIC)),A);equip(m,A,active(m,A),false);NonPokemonBatch75Test.hurt(m,A,active(m,A),950);NonPokemonBatch75Test.hurt(m,B,bench(m,B),980);m.endTurn(A);m.attack(B,"hit");triggerOrder(m);var q=m.damageAllocationPrompt(A);m.submitDamageAllocation(A,q.resolutionId(),q.step(),List.of(new ServerMatch.DamageCounterPlacement(B,active(m,B),2),new ServerMatch.DamageCounterPlacement(B,bench(m,B),2)));NonPokemonBatch67Test.settle(m);check(m.privateView(A).prizes().size()==5&&m.privateView(B).prizes().size()==5&&m.benchPokemonView(B).isEmpty(),"Spell Tag cascade did not preserve both KO awards");}
    static void metalGoggles(){var m=DynamicPassiveModifierTest.fixture(tag(),DynamicPassiveModifierTest.plainStadium(),EnergyProfile.fixed(EnergyType.COLORLESS,1),GeneratedRuleBatch8Test.hit(100,false),List.of(),0,NonPokemonBatch2Test.DATA.trainer("sm9_en_148").orElseThrow(),Map.of("basic",EnergyType.METAL,"evolved",EnergyType.PSYCHIC));UUID host=active(m,A);m.evolveByEffect(A,host,hand(m,A,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.playTrainer(A,hand(m,A,"tool").instanceId(),host);m.attachToolByEffect(A,B,EffectSourceZone.HAND,hand(m,B,"item").instanceId(),B,active(m,B));NonPokemonBatch75Test.hurt(m,A,host,250);m.endTurn(A);m.attack(B,"hit");triggerOrder(m);var q=m.damageAllocationPrompt(A);m.submitDamageAllocation(A,q.resolutionId(),q.step(),List.of(new ServerMatch.DamageCounterPlacement(B,active(m,B),4)));NonPokemonBatch67Test.settle(m);check(m.activePokemonView(B).damage()==40,"Metal Goggles incorrectly blocked counters from a Tool");}
}
